int prefix[MAX_H+1][MAX_W+1];
int dp[MAX_H][MAX_W][MAX_H][MAX_W][MAX_N+1];

int get_sum(int r1, int c1, int r2, int c2) {
    return prefix[r2+1][c2+1] - prefix[r1][c2+1] - prefix[r2+1][c1] + prefix[r1][c1];
}

int min_val(int a, int b) {
    return a < b ? a : b;
}

int max_val(int a, int b) {
    return a > b ? a : b;
}

int solve(int r1, int c1, int r2, int c2, int k) {
    if (k == 1) {
        return get_sum(r1, c1, r2, c2);
    }
    if (dp[r1][c1][r2][c2][k] != -1) {
        return dp[r1][c1][r2][c2][k];
    }

    int total = get_sum(r1, c1, r2, c2);
    int best = 0;

    // Try horizontal cuts
    for (int r = r1; r < r2; r++) {
        int top_sum = get_sum(r1, c1, r, c2);
        int bottom_sum = total - top_sum;
        if (top_sum >= best && bottom_sum >= best) {
            for (int i = 1; i < k; i++) {
                int left = solve(r1, c1, r, c2, i);
                int right = solve(r+1, c1, r2, c2, k-i);
                int current = min_val(left, right);
                if (current > best) {
                    best = current;
                }
            }
        }
    }

    // Try vertical cuts
    for (int c = c1; c < c2; c++) {
        int left_sum = get_sum(r1, c1, r2, c);
        int right_sum = total - left_sum;
        if (left_sum >= best && right_sum >= best) {
            for (int i = 1; i < k; i++) {
                int left = solve(r1, c1, r2, c, i);
                int right = solve(r1, c+1, r2, c2, k-i);
                int current = min_val(left, right);
                if (current > best) {
                    best = current;
                }
            }
        }
    }

    dp[r1][c1][r2][c2][k] = best;
    return best;
}

