int H, W, N;
int memo[101][101][101];
int computed[101][101][101];

int dp(int h, int w, int n) {
    if (n == 1) return h * w;
    if (h * w < n) return 0; // impossible, return 0
    if (computed[h][w][n]) return memo[h][w][n];
    computed[h][w][n] = 1;
    int best = 0;
    for (int k = 1; k < n; k++) {
        for (int cut = 1; cut < h; cut++) {
            int v = dp(cut, w, k);
            int v2 = dp(h-cut, w, n-k);
            int mn = v < v2 ? v : v2;
            if (mn > best) best = mn;
        }
        for (int cut = 1; cut < w; cut++) {
            int v = dp(h, cut, k);
            int v2 = dp(h, w-cut, n-k);
            int mn = v < v2 ? v : v2;
            if (mn > best) best = mn;
        }
    }
    memo[h][w][n] = best;
    return best;
}

