#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }
static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    ll H, W, N;
    if (scanf("%lld %lld %lld", &H, &W, &N) != 3) return 0;

    /*
      We need the maximum possible minimum area among N non-overlapping
      axis-aligned rectangles placed inside an H x W integer grid rectangle.
      Unused area is allowed.

      If every brother must get at least X area, then each rectangle must have
      integer side lengths (h_i, w_i) with h_i * w_i >= X.

      Since unused area is allowed, feasibility of X is equivalent to being able
      to place N rectangles each of area at least X.

      For a fixed rectangle width t (integer, 1..W), the minimum height needed
      to achieve area at least X is ceil(X / t). Thus in one horizontal strip of
      height H, the number of such rectangles of width t that can be stacked
      side-by-side is floor(W / t) * floor(H / ceil(X/t)) if arranged uniformly.
      But better is to think in columns:
        for each chosen width t, one rectangle consumes width t and needs height
        ceil(X/t), so within total height H we can stack floor(H / ceil(X/t))
        rectangles in that width-t column.
      Therefore each column of width t contributes:
        cap(t) = floor(H / ceil(X/t))
      and we may use up to floor(W / t) such columns if all same width.

      More generally, we want maximum number of rectangles obtainable by partitioning
      total width W into integer widths, where a column of width t yields cap(t)
      rectangles. This is an unbounded knapsack:
        dp[w] = max rectangles using exactly w width
        dp[w+t] = max(dp[w+t], dp[w] + cap(t))

      Then X is feasible iff max_{w<=W} dp[w] >= N.

      Constraints are not provided here, but this standard DP over width for each
      binary-searched X is acceptable when dimensions are moderate. We also exploit
      symmetry by using the smaller dimension as width to minimize DP size.
    */

    if (W > H) {
        ll tmp = W;
        W = H;
        H = tmp;
    }

    ll low = 0, high = H * W; // answer in [0, H*W]

    ll *dp = (ll *)malloc((W + 1) * sizeof(ll));
    ll *cap = (ll *)malloc((W + 1) * sizeof(ll));
    if (!dp || !cap) return 0;

    while (low < high) {
        ll mid = (low + high + 1) / 2; // test feasibility of mid

        for (ll t = 1; t <= W; ++t) {
            ll need_h = (mid + t - 1) / t;   // ceil(mid / t)
            if (need_h > H) cap[t] = 0;
            else cap[t] = H / need_h;
        }

        dp[0] = 0;
        for (ll w = 1; w <= W; ++w) dp[w] = -1;

        for (ll w = 0; w <= W; ++w) {
            if (dp[w] < 0) continue;
            for (ll t = 1; w + t <= W; ++t) {
                if (cap[t] == 0) continue;
                ll nv = dp[w] + cap[t];
                if (nv > dp[w + t]) dp[w + t] = nv;
            }
        }

        ll best = 0;
        for (ll w = 0; w <= W; ++w) best = maxll(best, dp[w]);

        if (best >= N) low = mid;
        else high = mid - 1;
    }

    printf("%lld\n", low);

    free(dp);
    free(cap);
    return 0;
}

