int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, N;
    cin >> H >> W >> N;

    vector<vector<long long>> a(H + 1, vector<long long>(W + 1));
    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            cin >> a[i][j];
        }
    }

    // 2D prefix sums
    vector<vector<long long>> ps(H + 1, vector<long long>(W + 1, 0));
    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            ps[i][j] = a[i][j] + ps[i - 1][j] + ps[i][j - 1] - ps[i - 1][j - 1];
        }
    }

    auto rectSum = [&](int r1, int c1, int r2, int c2) -> long long {
        if (r1 > r2 || c1 > c2) return 0;
        return ps[r2][c2] - ps[r1 - 1][c2] - ps[r2][c1 - 1] + ps[r1 - 1][c1 - 1];
    };

    // dp[i][j][k]:
    // maximum possible minimum inheritance value when dividing
    // subrectangle (1..i, 1..j) among k brothers,
    // using non-overlapping rectangles inside it, leftovers allowed.
    vector<vector<vector<long long>>> dp(
        H + 1, vector<vector<long long>>(W + 1, vector<long long>(N + 1, 0))
    );

    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            dp[i][j][1] = rectSum(1, 1, i, j);
        }
    }

    for (int k = 2; k <= N; ++k) {
        for (int i = 1; i <= H; ++i) {
            for (int j = 1; j <= W; ++j) {
                long long best = 0;

                // Horizontal split
                for (int x = 1; x < i; ++x) {
                    for (int t = 1; t < k; ++t) {
                        best = max(best, min(dp[x][j][t], dp[i - x][j][k - t]));
                    }
                }

                // Vertical split
                for (int y = 1; y < j; ++y) {
                    for (int t = 1; t < k; ++t) {
                        best = max(best, min(dp[i][y][t], dp[i][j - y][k - t]));
                    }
                }

                dp[i][j][k] = best;
            }
        }
    }

    long long ans = 0;

    // Since leaving land unclaimed is allowed, the used area can be any subrectangle.
    // Consider every subrectangle and place all N brothers inside it.
    for (int r1 = 1; r1 <= H; ++r1) {
        for (int r2 = r1; r2 <= H; ++r2) {
            int h = r2 - r1 + 1;
            for (int c1 = 1; c1 <= W; ++c1) {
                for (int c2 = c1; c2 <= W; ++c2) {
                    int w = c2 - c1 + 1;

                    // Build prefix sums for this subrectangle into top-left-based values
                    vector<vector<long long>> sub(h + 1, vector<long long>(w + 1, 0));
                    for (int i = 1; i <= h; ++i) {
                        for (int j = 1; j <= w; ++j) {
                            sub[i][j] = rectSum(r1, c1, r1 + i - 1, c1 + j - 1);
                        }
                    }

                    vector<vector<vector<long long>>> f(
                        h + 1, vector<vector<long long>>(w + 1, vector<long long>(N + 1, 0))
                    );

                    for (int i = 1; i <= h; ++i)
                        for (int j = 1; j <= w; ++j)
                            f[i][j][1] = sub[i][j];

                    for (int k = 2; k <= N; ++k) {
                        for (int i = 1; i <= h; ++i) {
                            for (int j = 1; j <= w; ++j) {
                                long long best = 0;
                                for (int x = 1; x < i; ++x) {
                                    for (int t = 1; t < k; ++t) {
                                        best = max(best, min(f[x][j][t], f[i - x][j][k - t]));
                                    }
                                }
                                for (int y = 1; y < j; ++y) {
                                    for (int t = 1; t < k; ++t) {
                                        best = max(best, min(f[i][y][t], f[i][j - y][k - t]));
                                    }
                                }
                                f[i][j][k] = best;
                            }
                        }
                    }

                    ans = max(ans, f[h][w][N]);
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

