    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        H = Integer.parseInt(st.nextToken());
        W = Integer.parseInt(st.nextToken());
        N = Integer.parseInt(st.nextToken());

        int[][] land = new int[H+1][W+1];
        for (int i = 1; i <= H; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 1; j <= W; j++) {
                land[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        // Build prefix sum
        prefix = new long[H+1][W+1];
        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                prefix[i][j] = land[i][j] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1];
            }
        }

        long totalSum = prefix[H][W];
        long low = 0, high = totalSum;
        long ans = 0;

        while (low <= high) {
            long mid = (low + high) / 2;
            if (canDivide(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        System.out.println(ans);
    }

    static long getSum(int r1, int c1, int r2, int c2) {
        return prefix[r2][c2] - prefix[r1-1][c2] - prefix[r2][c1-1] + prefix[r1-1][c1-1];
    }

    static boolean canDivide(long minValue) {
        // Try all possible vertical cuts between columns
        for (int c1 = 0; c1 <= W; c1++) {
            for (int c2 = c1; c2 <= W; c2++) {
                // We have two vertical strips: [1..c1] and [c2+1..W] possibly empty
                // Also a middle strip [c1+1..c2] that can be split horizontally

                // Count rectangles we can form in left strip
                int leftCount = countRectanglesInStrip(1, c1, minValue);
                if (leftCount > N) continue; // too many, but we can leave some unclaimed, so it's okay? Actually we want to maximize min, so having more than N is fine if we can select N.
                // We need exactly N rectangles total, we can leave some unclaimed. So we need at most N rectangles that meet minValue.
                // Actually we need to assign N rectangles, each >= minValue. So we need at least N rectangles with sum >= minValue.
                // So leftCount + middleCount + rightCount >= N

                int rightCount = countRectanglesInStrip(c2+1, W, minValue);
                if (leftCount + rightCount > N) continue;

                // For middle strip, we need to consider horizontal cuts
                int middleCount = countRectanglesInMiddle(c1+1, c2, minValue);

                if (leftCount + middleCount + rightCount >= N) {
                    return true;
                }
            }
        }
        return false;
    }

    static int countRectanglesInStrip(int cStart, int cEnd, long minValue) {
        if (cStart > cEnd) return 0;
        int count = 0;
        // For each possible top row and bottom row, check if sum >= minValue
        // But we want to maximize number of non-overlapping rectangles.
        // Actually we can just count how many disjoint rectangles we can fit in this strip.
        // Since all rectangles must be disjoint and within this strip, we can greedily take rectangles from top to bottom.
        int r = 1;
        while (r <= H) {
            int bestR = -1;
            for (int r2 = r; r2 <= H; r2++) {
                if (getSum(r, cStart, r2, cEnd) >= minValue) {
                    bestR = r2;
                    break;
                }
            }
            if (bestR == -1) break;
            count++;
            r = bestR + 1;
        }
        return count;
    }

    static int countRectanglesInMiddle(int cStart, int cEnd, long minValue) {
        if (cStart > cEnd) return 0;
        // For middle strip, we can also split horizontally, same logic
        int count = 0;
        int r = 1;
        while (r <= H) {
            int bestR = -1;
            for (int r2 = r; r2 <= H; r2++) {
                if (getSum(r, cStart, r2, cEnd) >= minValue) {
                    bestR = r2;
                    break;
                }
            }
            if (bestR == -1) break;
            count++;
            r = bestR + 1;
        }
        return count;
    }
