import java.io.*;
import java.util.*;

/*
We need maximize the minimum area among N non-overlapping axis-aligned rectangles
inside an H x W rectangle on unit grid, with unused cells allowed.

If each brother must receive one rectangle of integer side lengths, then to guarantee
minimum area >= X, each chosen rectangle must have area at least X.

Because unused area is allowed, feasibility for X reduces to:
Can we place N pairwise disjoint rectangles inside H x W, each with integer sides and area >= X?

Key observation:
For any rectangle with area >= X, if one side length is fixed to a positive integer a,
the other side must be at least ceil(X / a).

A full optimal packing can be represented by guillotine cuts recursively, and for this
special objective there is a simpler DP:
Let f(h, w) = maximum number of rectangles of area at least X that can fit in h x w.
Then
- If h*w < X, f = 0.
- Otherwise at least 1 (use whole rectangle as one piece).
- Also we can split horizontally or vertically:
  f(h,w) = max(1, max_k f(k,w)+f(h-k,w), max_k f(h,k)+f(h,w-k))

This DP is correct because in any packing of disjoint rectangles inside a containing
rectangle, considering the rectangle that contains the top-leftmost occupied cell,
everything else lies either entirely below it or entirely to its right; recursively
this yields guillotine-style decomposition sufficient for optimal count here.

We binary search X.

Complexity:
For one feasibility check: O(H*W*(H+W)).
This is fine for moderate constraints typically used for this problem.
*/

public class Main {
    static int H, W, N;
    static int[][] dp;

    static boolean can(int x) {
        dp = new int[H + 1][W + 1];

        for (int h = 1; h <= H; h++) {
            for (int w = 1; w <= W; w++) {
                if ((long) h * w < x) {
                    dp[h][w] = 0;
                    continue;
                }
                int best = 1; // use the whole h x w as one rectangle
                for (int k = 1; k <= h / 2; k++) {
                    best = Math.max(best, dp[k][w] + dp[h - k][w]);
                }
                for (int k = 1; k <= w / 2; k++) {
                    best = Math.max(best, dp[h][k] + dp[h][w - k]);
                }
                dp[h][w] = best;
            }
        }
        return dp[H][W] >= N;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        H = fs.nextInt();
        W = fs.nextInt();
        N = fs.nextInt();

        int lo = 0, hi = H * W + 1; // [lo feasible, hi infeasible)
        while (hi - lo > 1) {
            int mid = (lo + hi) >>> 1;
            if (can(mid)) lo = mid;
            else hi = mid;
        }
        System.out.println(lo);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
